def qaoa_maxcut_ansatz(G, beta, gamma) -> QuantumCircuit:  
    num_qubits = len(G.nodes())
    qc = QuantumCircuit(num_qubits, num_qubits)
    qr = [QuantumRegister(1, name=f"q[{i}]") for i in range(num_qubits)]
    cr = [ClassicalRegister(1, name=f"c[{i}]") for i in range(num_qubits)]
    qc = QuantumCircuit(qr, cr)

    for i in range(num_qubits):
        qc.h(qr[i])

    for i in range(num_qubits):
        for j in range(i+1, num_qubits):
            if (i, j) in G.edges() or (j, i) in G.edges():
                qc.append(MultiControlToffoliGate(1), [qr[i]] + [qr[j]] + qr[num_qubits:])
            else:
                qc.id(qr[i])

    qc.barrier()

    for i in range(num_qubits):
        qc.u1(gamma[i], qr[i])
        qc.u1(2 * beta[i], qr[num_qubits])

    qc.barrier()

    for i in range(num_qubits):
        for j in range(i+1, num_qubits):
            if (i, j) in G.edges() or (j, i) in G.edges():
                qc.append(MultiControlToffoliGate(1), [qr[i]] + [qr[j]] + qr[num_qubits:])
            else:
                qc.id(qr[i])

    qc.barrier()

    for i in range(num_qubits):
        qc.measure(qr[i], cr[i])

    return qc

